#include <algorithm>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

static const string D = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    while (q--) {
        int a, b;
        string s;
        cin >> a >> b >> s;
        vector<int> v;
        for (char c : s) v.push_back(c <= '9' ? c - '0' : (c >= 'a' ? c - 'a' : c - 'A') + 10);
        string out;
        size_t start = 0;
        while (start < v.size() && v[start] == 0) start++;
        while (start < v.size()) {
            long long rem = 0;
            for (size_t i = start; i < v.size(); i++) {
                long long cur = rem * a + v[i];
                v[i] = (int)(cur / b);
                rem = cur % b;
            }
            out.push_back(D[rem]);
            while (start < v.size() && v[start] == 0) start++;
        }
        if (out.empty()) out = "0";
        reverse(out.begin(), out.end());
        cout << out << '\n';
    }
    return 0;
}

